sys_variable_value.value:
(function execute(inputs, outputs) {
    var inputName = (inputs.name || "").toString().trim();
    var top10JSON = (inputs.name_json || "[]").toString().trim();

    if (!inputName) {
        outputs.matched_name = "NO_MATCH";
        return; 
    }

    try {
        var aiHelper = new x_1815796_itsmgr_0.AiBotHelper();
        var rawMatch = aiHelper.findClosestCompany(inputName, top10JSON);
        
        var cleanMatch = (rawMatch || "").replace(/^MATCHED_NAME:\s*/i, '').replace(/^["']|["']$/g, '').trim();
        
        outputs.matched_name = cleanMatch;
        
    } catch (e) {
        gs.error("AI Bot Helper failed in Flow Action: " + e.message);
        outputs.matched_name = "ERROR";
    }

})(inputs, outputs);

